```public double administrarMedicacao(int qtde) {
    if (quantidadeDisponivel >= qtde) {
        quantidadeDisponivel -= qtde;
        return qtde;
    }
    return 0;
}

public double administrarMedicacao(double peso, double dosagemPorQuilo) {
    double dose = peso * dosagemPorQuilo;
    if (quantidadeDisponivel >= dose) {
        quantidadeDisponivel -= dose;
        return dose;
    }
    return 0;
}

```public class AvaliacaoNeurodivergente extends Avaliacao {
    private int nivel;

    public AvaliacaoNeurodivergente(int nrInscricao, int nivel) {
        super(nrInscricao);
        this.nivel = nivel;
    }

    @Override
    public double contabilizarNotas(int acertosME, double disc1, double disc2) {
        super.contabilizarNotas(acertosME, disc1, disc2);
        final double INDICE = 1 + 0.1 + 0.1 * nivel;
        this.nota *= INDICE;
        this.nota = this.nota > 1000 ? 1000 : this.nota;
        definirSituacao();
        return this.nota;
    }
}

